{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a materially higher general cap, supported by the deal’s risk profile and diligence."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek a lower de minimis and a tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer period for general warranties"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Require robust title/capacity warranties, a separate high cap and a longer survival period."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "State that related claims are aggregated and that the thresholds do not apply to fraud, fundamental/title claims or specific indemnities."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Require specific, fair disclosure against the particular warranty, with sufficient detail for the Buyer to identify the nature and scope of the matter."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Prefer no general knowledge bar."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require both before Completion, with no deemed satisfaction merely on delivery of a consent that may be conditional or incomplete."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require repayment from Completion funds, direct lender payout mechanics, and delivery of the lender’s release and discharge evidence as a completion deliverable."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Require the Seller to fund them, or expressly treat them as debt-like items deducted from the price"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Ironquay IP — broaden protection beyond the SOW3 payment."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require completion of a documented investigation, preservation of evidence, prompt updates, and delivery of findings and regulator/individual communications."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Do not accept the Seller’s label alone as proof they are ordinary-course costs."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reject a blanket rule that every claim is time-barred unless expressly carved out; specify the applicable period and regime for each category."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is evidence of what the register records, not independent verification of good title, absence of encumbrances or authority to transfer."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Tax and IP should not be swept into the general regime."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

